selector_to_html = {"a[href=\"#split-kv-paged-attention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Split-KV \u4e0e paged attention<a class=\"headerlink\" href=\"#split-kv-paged-attention\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flash_attention_split_kv</span></code> \u662f\u9762\u5411\u957f KV \u573a\u666f\u7684\u663e\u5f0f\u524d\u5411 API\uff0c\u63a5\u53d7 <code class=\"docutils literal notranslate\"><span class=\"pre\">q:</span> <span class=\"pre\">[B,Hq,M,D]</span></code> \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">k/v:</span> <span class=\"pre\">[B,Hkv,N,D]</span></code>\uff0c\u8981\u6c42 <code class=\"docutils literal notranslate\"><span class=\"pre\">Hq</span> <span class=\"pre\">%</span> <span class=\"pre\">Hkv</span> <span class=\"pre\">==</span> <span class=\"pre\">0</span></code>\uff0c\u5e76\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">D</span></code> \u53d6 <code class=\"docutils literal notranslate\"><span class=\"pre\">{16,32,64,128}</span></code>\u3002\u9009\u62e9\u591a\u4e2a split \u65f6\uff0c\u5404 split \u8ba1\u7b97\u5c40\u90e8\u8f93\u51fa\u4e0e log-normalizer\uff0c\u518d\u7531\u7b2c\u4e8c\u4e2a kernel \u901a\u8fc7\u5168\u5c40 logsumexp \u5408\u5e76\u3002</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">paged_attention</span></code> \u63a5\u53d7 paged KV cache \u4e0e\u9010\u5e8f\u5217\u5143\u6570\u636e\uff1a</p>", "a[href=\"#piecewise-attention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Piecewise Attention<a class=\"headerlink\" href=\"#piecewise-attention\" title=\"Link to this heading\">#</a></h3><p>\u5bf9\u4e8e query \u884c <code class=\"docutils literal notranslate\"><span class=\"pre\">m</span></code> \u4e0e key \u5217 <code class=\"docutils literal notranslate\"><span class=\"pre\">n</span></code>\uff0c\u5f53\u53f3\u4e0b\u5bf9\u9f50\u7684\u6709\u7b26\u53f7\u504f\u79fb <code class=\"docutils literal notranslate\"><span class=\"pre\">N</span> <span class=\"pre\">-</span> <span class=\"pre\">M</span> <span class=\"pre\">+</span> <span class=\"pre\">m</span> <span class=\"pre\">-</span> <span class=\"pre\">n</span> <span class=\"pre\">&gt;=</span> <span class=\"pre\">dist_threshold</span></code> \u65f6\u7b97\u5b50\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">q2</span> <span class=\"pre\">@</span> <span class=\"pre\">k2</span></code>\uff0c\u5426\u5219\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">q1</span> <span class=\"pre\">@</span> <span class=\"pre\">k1</span></code>\u3002\u53cd\u5411\u4f1a\u628a <code class=\"docutils literal notranslate\"><span class=\"pre\">dScore</span></code> \u62c6\u5206\u5230\u4e24\u5957 Q/K \u4e0a\u3002\u6240\u6709\u8f93\u5165\u7684 head \u6570\u4e00\u81f4\uff08\u4e0d\u652f\u6301 GQA\uff09\uff0c<code class=\"docutils literal notranslate\"><span class=\"pre\">D</span></code> \u53d6\u503c\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">16</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">32</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">64</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">128</span></code>\u3002</p><p>Piecewise Attention \u4e3a NLPE\uff08Non-Linearized Position Embedding\uff09\u5f15\u5165\uff0cAquila-2-34B \u7528\u5b83\u5728\u7ebf\u6027\u4f4d\u7f6e\u8868\u793a\u4e4b\u5916\u6309\u8ddd\u79bb\u9608\u503c\u5207\u6362\u4f4d\u7f6e\u8868\u793a\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7a20\u5bc6\u6ce8\u610f\u529b<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><h3>FlashAttention<a class=\"headerlink\" href=\"#flashattention\" title=\"Link to this heading\">#</a></h3><p>\u5b8c\u6574\u63a5\u53e3\u5982\u4e0b\uff1a</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u7a20\u5bc6\u6ce8\u610f\u529b<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><h3>FlashAttention<a class=\"headerlink\" href=\"#flashattention\" title=\"Link to this heading\">#</a></h3><p>\u5b8c\u6574\u63a5\u53e3\u5982\u4e0b\uff1a</p>", "a[href=\"#sageattention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">SageAttention<a class=\"headerlink\" href=\"#sageattention\" title=\"Link to this heading\">#</a></h3><p>\u540c\u65f6\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">HND</span></code>\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">[B,H,N,D]</span></code>\uff09\u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">NHD</span></code>\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">[B,N,H,D]</span></code>\uff09\u5e03\u5c40\u3002\u9ed8\u8ba4\u60c5\u51b5\u4e0b Q \u6309 128 \u4e2a token \u5206\u5757\u91cf\u5316\uff0cK \u6309 64 \u4e2a token \u5206\u5757\u91cf\u5316\u3002\u524d\u5411 kernel \u63a5\u53d7\u5e03\u5c14\u6216\u52a0\u6027 attention mask\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u63a8\u7406\u4e0e\u7a00\u758f\u6ce8\u610f\u529b<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><h3>Split-KV \u4e0e paged attention<a class=\"headerlink\" href=\"#split-kv-paged-attention\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flash_attention_split_kv</span></code> \u662f\u9762\u5411\u957f KV \u573a\u666f\u7684\u663e\u5f0f\u524d\u5411 API\uff0c\u63a5\u53d7 <code class=\"docutils literal notranslate\"><span class=\"pre\">q:</span> <span class=\"pre\">[B,Hq,M,D]</span></code> \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">k/v:</span> <span class=\"pre\">[B,Hkv,N,D]</span></code>\uff0c\u8981\u6c42 <code class=\"docutils literal notranslate\"><span class=\"pre\">Hq</span> <span class=\"pre\">%</span> <span class=\"pre\">Hkv</span> <span class=\"pre\">==</span> <span class=\"pre\">0</span></code>\uff0c\u5e76\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">D</span></code> \u53d6 <code class=\"docutils literal notranslate\"><span class=\"pre\">{16,32,64,128}</span></code>\u3002\u9009\u62e9\u591a\u4e2a split \u65f6\uff0c\u5404 split \u8ba1\u7b97\u5c40\u90e8\u8f93\u51fa\u4e0e log-normalizer\uff0c\u518d\u7531\u7b2c\u4e8c\u4e2a kernel \u901a\u8fc7\u5168\u5c40 logsumexp \u5408\u5e76\u3002</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">paged_attention</span></code> \u63a5\u53d7 paged KV cache \u4e0e\u9010\u5e8f\u5217\u5143\u6570\u636e\uff1a</p>", "a[href=\"#minimax-m3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MiniMax M3 \u7a00\u758f\u6ce8\u610f\u529b<a class=\"headerlink\" href=\"#minimax-m3\" title=\"Link to this heading\">#</a></h3><p>M3 \u8def\u5f84\u4f7f\u7528 vLLM \u517c\u5bb9\u7684 paged cache\uff0c\u7a00\u758f block \u56fa\u5b9a\u4e3a 128 \u4e2a token\uff1a</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d4b\u8bd5\u4e0e\u57fa\u51c6<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u5b89\u88c5\u5f00\u53d1\u4f9d\u8d56\u540e\uff0c\u65e0\u9700\u63a2\u6d4b\u52a0\u901f\u5668\u5373\u53ef\u5217\u51fa\u7b97\u5b50\u6e05\u5355\uff1a</p>", "a[href=\"#flashattention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlashAttention<a class=\"headerlink\" href=\"#flashattention\" title=\"Link to this heading\">#</a></h3><p>\u5b8c\u6574\u63a5\u53e3\u5982\u4e0b\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9012\u5f52\u4e0e\u7ebf\u6027\u6ce8\u610f\u529b<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>GLA\u3001GDN2 \u4e0e KDA \u4f7f\u7528 sequence-first \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">[B,T,H,D]</span></code>\u3002Gated Delta Rule \u9ed8\u8ba4 <code class=\"docutils literal notranslate\"><span class=\"pre\">head_first=True</span></code>\uff0c\u5373 head-first \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">[B,H,T,D]</span></code>\uff0c\u540c\u65f6\u63a5\u53d7 sequence-first \u8f93\u5165\u3002\u591a\u6570\u9012\u5f52 API \u8fd4\u56de <code class=\"docutils literal notranslate\"><span class=\"pre\">(output,</span> <span class=\"pre\">final_state)</span></code>\uff0c\u5e76\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">cu_seqlens</span></code> \u652f\u6301 packed \u53d8\u957f\u5e8f\u5217\u3002</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bbe\u5907\u9009\u62e9<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u540e\u7aef\u8def\u7531\u662f\u9010\u7b97\u5b50\u7684\uff1a\u9876\u5c42 GDN2/KDA API \u4f1a\u9009\u62e9\u71e7\u539f\u3001MetaX \u4e0e\u6469\u5c14\u7ebf\u7a0b\u7684\u4e13\u7528\u5b9e\u73b0\uff0cMiniMax M3 \u4f1a\u9009\u62e9\u5176 MetaX \u5b9e\u73b0\u3002\u80fd\u591f\u8bc6\u522b\u540e\u7aef\u5e76\u4e0d\u8868\u793a\u6bcf\u4e2a\u7b97\u5b50\u90fd\u5df2\u5728\u8be5\u540e\u7aef\u5b9e\u73b0\u6216\u9a8c\u8bc1\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
